select case when customers.age >= 59 then 'high' when customers.age >= 37 then 'mid' else 'low' end as age_bucket, count(case when sessions.browser = 'Safari' then 1 end) as safari_count from sessions join customers on sessions.customer_id = customers.id where sessions.country in ('SG', 'JP') group by case when customers.age >= 59 then 'high' when customers.age >= 37 then 'mid' else 'low' end order by safari_count desc
